<?php
use GhoroaHat\Rewards\{Settings,SMS};
$old=Settings::all();$old_secret=get_option('ghr_sms_credential');global $ghr_sms_count;$ghr_sms_count=0;
function sms_check($ok,$message){global $ghr_sms_count;++$ghr_sms_count;if(!$ok){throw new RuntimeException($message);}echo "PASS $message\n";}
try{
Settings::save(array('sms_endpoint'=>'https://1.1.1.1/sms','sms_enabled'=>true));SMS::save_secret('fixture-only-not-a-real-credential');sms_check(!str_contains(get_option('ghr_sms_credential'),'fixture-only-not-a-real-credential'),'SMS credential encrypted at rest');
$mock=static function($pre,$args,$url){sms_check($url==='https://1.1.1.1/sms','Configured gateway endpoint');sms_check($args['headers']['Authorization']==='Bearer fixture-only-not-a-real-credential','Credential supplied only to configured HTTPS request');sms_check(isset($args['headers']['Idempotency-Key']),'Gateway idempotency header');$body=json_decode($args['body'],true);sms_check($body['to']==='+8801712345678'&&$body['message']==='Fixture message','Configurable JSON gateway payload');return array('response'=>array('code'=>202,'message'=>'Accepted'),'body'=>'{}','headers'=>array(),'cookies'=>array());};add_filter('pre_http_request',$mock,10,3);sms_check(SMS::send('+8801712345678','Fixture message','sms-fixture'),'Gateway accepted response');remove_filter('pre_http_request',$mock,10);$rejected=false;try{Settings::save(array('sms_endpoint'=>'http://127.0.0.1/private'));}catch(DomainException $e){$rejected=true;}sms_check($rejected,'Unsafe HTTP/private endpoint rejected');echo "SMS PASS: $ghr_sms_count assertions (HTTP mocked; no real messages sent)\n";
}finally{update_option('ghr_settings',$old,false);if(false===$old_secret){delete_option('ghr_sms_credential');}else{update_option('ghr_sms_credential',$old_secret,false);}}
